mapper.select:
SELECT c.*, cp.unread_count, CASE WHEN c.user_id = #{userId} THEN c.target_id ELSE c.user_id END AS other_user_id, ou.nickname AS other_user_name, ou.avatar AS other_user_avatar, (SELECT s.name FROM shops AS s WHERE s.owner_id = ou.id AND s.type = CASE WHEN c.category = 'service' THEN 'service' ELSE 'mall' END AND s.archived_at IS NULL LIMIT 1) AS other_shop_name, (SELECT s.logo FROM shops AS s WHERE s.owner_id = ou.id AND s.type = CASE WHEN c.category = 'service' THEN 'service' ELSE 'mall' END AND s.archived_at IS NULL LIMIT 1) AS other_shop_logo, other_cp.last_read_message_id AS other_last_read_message_id FROM conversations AS c INNER JOIN conversation_participants AS cp ON cp.conversation_id = c.id AND cp.user_id = #{userId} INNER JOIN conversation_participants other_cp ON other_cp.conversation_id = c.id AND other_cp.user_id <> #{userId} LEFT JOIN users AS ou ON ou.id = CASE WHEN c.user_id = #{userId} THEN c.target_id ELSE c.user_id END WHERE cp.deleted_at IS NULL
AND c.category IN
#{category}
ORDER BY COALESCE(c.last_message_at, c.updated_at) DESC, c.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM conversations AS c INNER JOIN conversation_participants AS cp ON cp.conversation_id = c.id AND cp.user_id = #{userId} WHERE cp.deleted_at IS NULL
AND c.category IN
#{category}

SELECT m.*
FROM messages AS m
WHERE m.conversation_id = #{conversationId}
  AND m.sender_id = #{senderId}
  AND m.client_message_id = #{clientMessageId}
  AND m.deleted_at IS NULL
LIMIT 1
FOR UPDATE

SELECT 
FROM messages AS m
LEFT JOIN users AS u ON u.id = m.sender_id
WHERE m.conversation_id = #{conversationId}
  AND m.deleted_at IS NULL

    AND m.id > #{afterMessageId}


    AND m.id < #{beforeId}

ORDER BY m.id DESC
LIMIT #{limit}

