UPDATE conversation_participants
SET unread_count = unread_count + 1,
    deleted_at = NULL
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}

UPDATE messages
SET is_read = 1, read_at = NOW()
WHERE conversation_id = #{conversationId}
  AND receiver_id = #{userId}
  AND is_read = 0
  AND deleted_at IS NULL

    AND id <= #{lastMessageId}

