UPDATE conversation_participants
SET deleted_at = NOW(),
    cleared_before_message_id = GREATEST(
        COALESCE(cleared_before_message_id, 0),
        COALESCE(#{clearedBeforeMessageId}, 0)
    ),
    unread_count = 0
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

UPDATE conversation_participants
SET deleted_at = NULL
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
